#include <iostream>
#include <stdexcept>
#include <string>

int convertir(const std::string& texto) {
    try {
        return std::stoi(texto);
    } catch (const std::invalid_argument&) {
        throw std::runtime_error("no es un número: " + texto);
    }
}

int main() {
    try {
        std::cout << convertir("42") << '\n';
        std::cout << convertir("cuarenta") << '\n';
    } catch (const std::runtime_error& error) {
        std::cerr << "Error: " << error.what() << '\n';
        return 1;
    }
    return 0;
}

