class ErrorDeValidacion(Exception):
    """La entrada no cumple las reglas del dominio."""

class EdadInvalida(ErrorDeValidacion):
    def __init__(self, valor):
        super().__init__(f"edad inválida: {valor}")
        self.valor = valor

def validar_edad(edad):
    if not isinstance(edad, int):
        raise TypeError("la edad debe ser un entero")
    if edad < 0 or edad > 120:
        raise EdadInvalida(edad)
    return edad

for valor in [-5, "20", 30]:
    try:
        print("ok", validar_edad(valor))
    except EdadInvalida as error:
        print("EdadInvalida:", error, "->", error.valor)
    except TypeError as error:
        print("TypeError:", error)

class ErrorDeDato(Exception):
    """Una fila del archivo no se puede procesar."""

def convertir(fila):
    try:
        producto = fila["producto"].strip()
        unidades = int(fila["unidades"])
        precio = float(fila["precio"])
    except KeyError as error:
        raise ErrorDeDato(f"falta la columna {error}") from error
    except ValueError as error:
        raise ErrorDeDato(f"valor no numérico en {fila}") from error
    if unidades < 0 or precio <= 0:
        raise ErrorDeDato(f"valores fuera de rango en {producto}")
    return producto, unidades * precio

filas = [
    {"producto": "teclado", "unidades": "3", "precio": "120.0"},
    {"producto": "monitor", "unidades": "x", "precio": "900.0"},
    {"producto": "mouse", "unidades": "5"},
    {"producto": "cable", "unidades": "-2", "precio": "15.0"},
]

total = 0
errores = []
for fila in filas:
    try:
        producto, importe = convertir(fila)
    except ErrorDeDato as error:
        errores.append(str(error))
    else:
        total += importe
        print("ok:", producto, importe)

print("total:", total)
print("errores:", len(errores))
for error in errores:
    print("-", error)

