class ErrorDeFormato(Exception):
    def __init__(self, campo, valor):
        super().__init__(f"{campo}: '{valor}' no es un entero")
        self.campo = campo
        self.valor = valor

def a_entero(texto, campo):
    try:
        return int(texto)
    except (TypeError, ValueError) as error:
        raise ErrorDeFormato(campo, texto) from error

datos = [("edad", "30"), ("edad", "treinta"), ("peso", "72.5")]
for campo, texto in datos:
    try:
        print(campo, "=", a_entero(texto, campo))
    except ErrorDeFormato as error:
        print("ErrorDeFormato:", error, "| campo:", error.campo)

class ErrorDeConfiguracion(Exception):
    pass

def leer_puerto(config):
    if "puerto" not in config:
        raise ErrorDeConfiguracion("falta la clave 'puerto'")
    try:
        puerto = int(config["puerto"])
    except ValueError as error:
        raise ErrorDeConfiguracion("el puerto debe ser numérico") from error
    if not 1 <= puerto <= 65535:
        raise ErrorDeConfiguracion(f"puerto fuera de rango: {puerto}")
    return puerto

configs = [{"puerto": "8080"}, {}, {"puerto": "ochenta"}, {"puerto": "70000"}]
for config in configs:
    try:
        puerto = leer_puerto(config)
    except ErrorDeConfiguracion as error:
        print("error:", error)
    else:
        print("ok:", puerto)
